import React, { useState } from "react";
import "../Dashboard/WeatherDashboard.css"
import { useEffect } from "react";
import "./WeatherResults.css"; // Import the CSS file
import "../styles/global.css";


const WeatherResults = ({ results, hourlyResults }) => {
    const temp = results.main.temp;
    const celsius = (temp - 273.15).toFixed(0);
    const location = results.name;
    const weatherDescription = results.weather[0].description;
    const highest = (parseInt(results.main.temp_min) - 273.15).toFixed(2);
    const lowest = (parseInt(results.main.temp_max) - 273.15).toFixed(2);
    const [hourlyData, setHourlyData] = useState([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [currentHours, currentMins, currentSecs] = new Date().toLocaleTimeString('en-US').split(':');
    let time;
    let hourlyTemp;

    const fetchHourlyWeather = () => {
        const tempData = [];
        const hours = hourlyResults?.days[0]?.hours;
        // let dataHours = hours.find(item => convertTo12HourFormat(item.datetime) = currentHours);
        hours.forEach(hour => {
                time = convertTo12HourFormat(hour.datetime);

                hourlyTemp = hour.temp;
                tempData.push({ time, hourlyTemp });
            });
        setHourlyData(tempData);
    };

    const handleNext = () => {
        setCurrentIndex((prevIndex) => (prevIndex + 1) %hourlyData.length);
    };

    const convertTo12HourFormat = (time) => {
        const [hours, minutes, seconds] = time.split(':');
        const hoursIn12Format = (hours % 12) || 12; // Convert 0 to 12 for midnight
        const ampm = hours < 12 ? 'am' : 'pm'; // Check the original hours for am/pm
        return currentHours = hours?  `${hoursIn12Format}:${minutes}${ampm}` : 'null';
    };

    // const handlePrev = () => {
    //     setCurrentIndex((prevIndex) => (prevIndex - 1 + hourlyData.length))
    // };

    useEffect(() => {
        if (hourlyResults) {
            fetchHourlyWeather(hourlyResults);
        }
    }, [hourlyResults]);


    return (
        <>
            <div className="card">
                <h2>{location}</h2>
                <h1>{celsius}&deg;C</h1>
                <p>{weatherDescription}</p>
                <div className="">
                    <p>H: {highest}</p>
                    <p>L: {lowest}</p>
                </div>
            </div>

            <div className="card">
                {/* <div className="arrow left" onClick={handlePrev}>&lt;</div> */}
                <ul className="flex list-none overflow-x">
                    {hourlyData.map((data, index) => (
                                <li className= "flex-column" key={index}>
                                   <p>{data.time}</p>
                                   <p> {data.hourlyTemp}°C</p>   
                                </li>
                            ))}   
                    {/* {hourlyData.length > 0 && (
                        <li className="flex-column" key={currentIndex}>
                            <p>{hourlyData[currentIndex].time}</p>
                            <p>{hourlyData[currentIndex].hourlyTemp}°C</p>
                        </li>
                    )} */}
                </ul>
                {/* <div className="arrow right" onClick={handleNext}>&gt;</div> */}
            </div>
        </>
    );

}

export default WeatherResults;
